<?php

declare(strict_types=1);

namespace Guard\Config\Project;

use Guard\Diagnostic\PolicyException;
use Guard\Structure\Markdown\HeadingParser;
use JsonException;
use Symfony\Component\Yaml\Yaml;

/**
 * Creates a versioned guard policy for the tools present in the target project.
 */
final class Initializer
{
    /**
     * @param ?list<string> $imports null selects presets from the project; a list imports only those names
     * @throws PolicyException when guard.yaml exists, cannot be created, or names an unknown preset
     * @throws JsonException when composer.json or composer.lock is malformed
     */
    public function write(string $path, ?array $imports = null): void
    {
        if (file_exists($path) || is_link($path)) {
            throw new PolicyException('Cannot create ' . $path . ': it already exists. Review the existing policy instead of overwriting it.');
        }
        $data = $this->configuration(dirname($path), $imports);
        $source = "# Project policy. Required rules fail; recommendations warn.\n" . Yaml::dump($data, 12, 2, Yaml::DUMP_EMPTY_ARRAY_AS_SEQUENCE);
        $handle = @fopen($path, 'x');
        if ($handle === false) {
            throw new PolicyException('Cannot create ' . $path . '. It must not exist and its directory must be writable.');
        }
        try {
            if (fwrite($handle, $source) !== strlen($source)) {
                throw new PolicyException('Could not finish writing ' . $path . '. Check disk space.');
            }
        } finally {
            fclose($handle);
        }
    }
    /**
     * Builds a project policy that imports shipped presets and keeps project-specific sections inline.
     *
     * @param ?list<string> $imports null selects presets from the project; a list imports only those names
     * @return array<string, mixed>
     * @throws JsonException when composer.json or composer.lock is malformed
     * @throws PolicyException when an import name is unknown or a preset cannot be read
     */
    public function configuration(string $root, ?array $imports = null): array
    {
        $names = (new PresetSelector())->select($root, $imports);
        $document = ['version' => 1];
        $paths = (new PresetCatalog())->imports($root, $names);
        if ($paths !== []) {
            $document['imports'] = $paths;
        }
        if (in_array('metrics', $names, true)) {
            $document['metrics'] = ['source' => (new ToolDetector())->sources($root), 'exclude' => []];
        }
        $readme = $this->readme($root);
        if ($readme !== null) {
            $document['documentation'] = $readme;
        }
        $document = (new PresetOverrides())->apply($root, $names, $document);

        return (new LegacyMigration())->migrate($root, $document, in_array('disable-doc', $names, true));
    }

    /**
     * Returns the current README headings when the project has a README.
     *
     * @return ?array<string, mixed>
     */
    public function readme(string $root): ?array
    {
        if (!is_file($root . '/README.md')) {
            return null;
        }
        $source = file_get_contents($root . '/README.md');
        $headings = [];
        foreach ((new HeadingParser())->parse($source === false ? '' : $source) as $heading) {
            $headings[] = $heading->notation();
        }

        return ['files' => ['README.md' => ['headings' => $headings]], 'scan' => ['README.md']];
    }

    /**
     * Returns the standard metric limits shipped in rules/metrics.yaml.
     *
     * @return array<string, array<string, int>>
     * @throws PolicyException when metrics.yaml does not define integer limits
     */
    public function limits(): array
    {
        return (new PresetCatalog())->limits();
    }
    /**
     * @param list<string> $sources
     * @return array<string, mixed>
     */
    public function structure(array $sources, bool $hasUnitTests = false): array
    {
        $directories = [['path' => '**', 'deny_dirs' => ['scripts', 'Scripts']]];
        foreach ($sources as $source) {
            $directories[] = ['path' => $source, 'allow' => [], 'max_dirs' => 20];
            $directories[] = ['path' => $source . '/**', 'forbid_empty' => true, 'allow' => ['*.php'],
                'deny' => ['*Helper.php', '*Helpers.php', '*Manager.php', '*Util.php', '*Utils.php', '*Service.php', '*Evidence.php', '*Evidences.php', '*Outcome.php', '*Outcomes.php', '*Probe.php', '*Probes.php'],
                'file_case' => 'pascal', 'dir_case' => 'pascal', 'max_files' => 15, 'max_dirs' => 20];
        }
        if ($hasUnitTests) {
            $directories[] = ['path' => 'tests/Unit', 'allow' => []];
            $directories[] = ['path' => 'tests/Unit/**', 'forbid_empty' => true, 'allow' => ['*Test.php'],
                'file_case' => 'pascal', 'dir_case' => 'pascal', 'max_files' => 15, 'max_dirs' => 20];
        }
        $directories[] = ['path' => 'skills/*', 'require' => ['SKILL.md'], 'forbid_empty' => true];
        return ['paths' => ['.'], 'exclude' => ['.git', '.idea', '.claude', '.agents', '.codex', '.cursor', '.gemini', '.entire', '.entrie', '.phpunit.cache', 'build', 'projects', 'vendor'], 'directories' => $directories];
    }
}
=====RECOMMENDATIONS
<?php

declare(strict_types=1);

namespace Guard\Config\Project;

use JsonException;

/**
 * Builds strict tool-specific field constraints for installed development tools.
 */
final class Recommendations
{
    /**
     * @return list<array<string, mixed>>
     * @throws JsonException
     */
    public function rules(string $root): array
    {
        $packages = (new ToolDetector())->packages($root);
        $rules = [];
        if (isset($packages['phpstan/phpstan']) || isset($packages['k-kinzal/phpstan-guard-rules'])) {
            $path = $this->existing($root, ['phpstan.neon', 'phpstan.neon.dist']);
            if ($path !== null) {
                $rules[] = $this->exact('phpstan.level', $path, 'neon', '/parameters/level', 'max');
                if (isset($packages['k-kinzal/phpstan-guard-rules'])) {
                    $rules[] = $this->exact('phpstan.all-rules', $path, 'neon', '/parameters/toolkit/allRules', true);
                }
            }
        }
        if (isset($packages['phpunit/phpunit'])) {
            $path = $this->existing($root, ['phpunit.xml', 'phpunit.xml.dist']);
            if ($path !== null) {
                $rules = array_merge($rules, $this->phpunit($path, $packages['phpunit/phpunit']));
            }
        }
        if (is_file($root . '/composer.json')) {
            $rules[] = $this->exact('composer.sort-packages', 'composer.json', 'json', '/config/sort-packages', true, 'recommended');
        }
        return $rules;
    }
    /**
     * @return list<array<string, mixed>>
     */
    public function phpunit(string $file, string $version): array
    {
        $rules = [];
        foreach (['beStrictAboutChangesToGlobalState', 'beStrictAboutOutputDuringTests', 'beStrictAboutTestsThatDoNotTestAnything', 'enforceTimeLimit'] as $attribute) {
            $rules[] = $this->exact('phpunit.' . $attribute, $file, 'xml', '/phpunit/@' . $attribute, 'true');
        }
        $legacy = preg_match('/^[~^]?9(?:\.|$)/', $version) === 1;
        $attributes = $legacy ? ['failOnWarning', 'failOnRisky', 'failOnIncomplete', 'failOnSkipped'] : ['failOnAllIssues', 'requireCoverageMetadata', 'beStrictAboutCoverageMetadata'];
        foreach ($attributes as $attribute) {
            $rules[] = $this->exact('phpunit.' . $attribute, $file, 'xml', '/phpunit/@' . $attribute, 'true');
        }
        return $rules;
    }
    /**
     * @param list<string> $candidates
     */
    public function existing(string $root, array $candidates): ?string
    {
        foreach ($candidates as $file) {
            if (is_file($root . '/' . $file)) {
                return $file;
            }
        }
        return null;
    }
    /**
     * @param bool|string $value
     * @return array<string, mixed>
     */
    public function exact(string $id, string $file, string $format, string $select, $value, string $level = 'required'): array
    {
        return ['id' => $id, 'file' => $file, 'format' => $format, 'select' => $select, 'level' => $level, 'assert' => ['equals' => $value]];
    }
}
=====TOOLDETECTOR
<?php

declare(strict_types=1);

namespace Guard\Config\Project;

use JsonException;

/**
 * Discovers tools and source roots from the project's own Composer files.
 */
final class ToolDetector
{
    /**
     * @return array<string, mixed>
     * @throws JsonException when a Composer file is malformed
     * @throws JsonException
     */
    public function manifest(string $root, string $file = 'composer.json'): array
    {
        $source = is_file($root . '/' . $file) ? file_get_contents($root . '/' . $file) : false;
        $data = $source === false ? [] : json_decode($source, true, 512, JSON_THROW_ON_ERROR);
        $mapping = [];
        foreach (is_array($data) ? $data : [] as $key => $value) {
            if (is_string($key)) {
                $mapping[$key] = $value;
            }
        }
        return $mapping;
    }
    /**
     * @return array<string, string>
     * @throws JsonException
     */
    public function packages(string $root): array
    {
        $manifest = $this->manifest($root);
        $packages = [];
        foreach (['require', 'require-dev'] as $section) {
            if (!isset($manifest[$section]) || !is_array($manifest[$section])) {
                continue;
            }
            foreach ($manifest[$section] as $name => $version) {
                if (is_string($name) && is_string($version)) {
                    $packages[$name] = $version;
                }
            }
        }
        $locked = $this->manifest($root, 'composer.lock');
        foreach (['packages', 'packages-dev'] as $section) {
            $entries = $locked[$section] ?? [];
            foreach (is_array($entries) ? $entries : [] as $entry) {
                if (is_array($entry) && is_string($entry['name'] ?? null) && is_string($entry['version'] ?? null)) {
                    $packages[$entry['name']] = ltrim($entry['version'], 'v');
                }
            }
        }
        return $packages;
    }
    /**
     * @return list<string>
     * @throws JsonException
     */
    public function sources(string $root): array
    {
        $manifest = $this->manifest($root);
        $autoload = $manifest['autoload'] ?? [];
        $mappings = is_array($autoload) ? ($autoload['psr-4'] ?? []) : [];
        $paths = [];
        foreach (is_array($mappings) ? $mappings : [] as $entry) {
            foreach (is_array($entry) ? $entry : [$entry] as $path) {
                if (is_string($path) && $path !== '' && is_dir($root . '/' . $path)) {
                    $paths[] = rtrim($path, '/');
                }
            }
        }
        if ($paths === [] && is_dir($root . '/src')) {
            $paths[] = 'src';
        }
        return array_values(array_unique($paths));
    }
}

